# name: shared_final_digit_match_rate
# description: Yes-rate for targets that end in the final digit shared by all (>=2) examples (e.g. 28,98 -> 38, 58); observed > null means the model under-endorses targets fitting a shared last-digit rule (treats it as just one diluted property), observed < null means it over-endorses them.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    m = {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        d = {e % 10 for e in ex}
        m[s] = d.pop() if (len(ex) >= 2 and len(d) == 1) else -1
    fd = sets.map(m).to_numpy()
    t = df["target"].astype(int).to_numpy() % 10
    sel = (fd >= 0) & (t == fd)
    if sel.sum() == 0:
        return 0.0
    return float(df["rating"].astype(float).to_numpy()[sel].mean())

# name: size_principle_violator_gap
# description: Among parity-homogeneous sets, yes-rate for parity-VIOLATING targets in 3-4-example sets minus in 2-example sets; observed < null means people reject rule violators more sharply as examples accumulate (a size-principle effect the model lacks), observed > null the reverse.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    uniq = pd.Series(sets.unique())
    par = {}
    for s in uniq:
        ex = [int(x) for x in s.split(",")]
        r = {e % 2 for e in ex}
        par[s] = (len(ex), r.pop() if len(r) == 1 else -1)
    n = sets.map(lambda s: par[s][0]).to_numpy()
    p = sets.map(lambda s: par[s][1]).to_numpy()
    t = df["target"].astype(int).to_numpy() % 2
    y = df["rating"].astype(float).to_numpy()
    viol = (p >= 0) & (t != p)
    big = viol & (n >= 3)
    small = viol & (n == 2)
    if big.sum() == 0 or small.sum() == 0:
        return 0.0
    return float(y[big].mean() - y[small].mean())

# name: parity_only_hit_dilution_slope
# description: For parity-homogeneous sets, among targets that match the shared parity but none of the set's other shared multiple-of-m (3..12) or final-digit properties, the yes-rate in sets with >=2 such extra shared properties minus sets with 0; the model's normalized overlap predicts strong dilution (negative), so observed > null means people treat parity as sufficient regardless of how many other properties the examples share, observed < null means dilution is even stronger.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    info = {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        ms = [m for m in range(3, 13) if all(e % m == 0 for e in ex)]
        d = {e % 10 for e in ex}
        fd = d.pop() if (len(ex) >= 2 and len(d) == 1) else -1
        pr = {e % 2 for e in ex}
        par = pr.pop() if len(pr) == 1 else -1
        info[s] = (par, ms, fd)
    t = df["target"].astype(int).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    n_extra = np.zeros(len(df)); keep = np.zeros(len(df), dtype=bool)
    sv = sets.to_numpy()
    for s, (par, ms, fd) in info.items():
        idx = sv == s
        if par < 0:
            continue
        tt = t[idx]
        k = (tt % 2 == par)
        for m in ms:
            k &= (tt % m != 0)
        if fd >= 0:
            k &= (tt % 10 != fd)
        keep[idx] = k
        n_extra[idx] = len(ms) + (1 if fd >= 0 else 0)
    a = keep & (n_extra >= 2)
    b = keep & (n_extra == 0)
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(y[a].mean() - y[b].mean())

# name: odd_set_even_target_rate
# description: Yes-rate for even targets when all (>=2) examples are odd; observed > null means the model's single parity salience makes people look stricter about odd sets than they are (people tolerate parity violations of odd sets), observed < null the reverse.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    uniq = sets.unique()
    m = {}
    for s in uniq:
        ex = [int(x) for x in s.split(",")]
        m[s] = len(ex) >= 2 and all(e % 2 == 1 for e in ex)
    allodd = sets.map(m).to_numpy().astype(bool)
    even = (df["target"].astype(int).to_numpy() % 2) == 0
    sel = allodd & even
    if sel.sum() == 0:
        return 0.0
    return float(df["rating"].astype(float).to_numpy()[sel].mean())

# name: round_number_target_bonus
# description: In sets whose examples are not all multiples of 10, yes-rate for targets that are multiples of 10 minus other targets of the same parity as the set (even sets only); observed > null means people favour round-number targets a priori (a bias the model, which only credits shared properties, lacks), observed < null the reverse.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    ok = {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        ok[s] = all(e % 2 == 0 for e in ex) and not all(e % 10 == 0 for e in ex)
    o = sets.map(ok).to_numpy().astype(bool)
    t = df["target"].astype(int).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    r = o & (t % 10 == 0)
    nr = o & (t % 2 == 0) & (t % 10 != 0)
    if r.sum() == 0 or nr.sum() == 0:
        return 0.0
    return float(y[r].mean() - y[nr].mean())

# name: unstructured_set_inside_span_rate
# description: Yes-rate for targets strictly inside [min,max] of sets whose examples do NOT share parity; observed < null means the model over-endorses in-span targets when there is no shared arithmetic rule (its magnitude bounds dominate a near-empty profile), observed > null means people generalize across the span even more than predicted.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    lo, hi, mixed = {}, {}, {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        lo[s], hi[s] = min(ex), max(ex)
        mixed[s] = len({e % 2 for e in ex}) > 1
    t = df["target"].astype(int).to_numpy()
    sel = sets.map(mixed).to_numpy().astype(bool) & (t > sets.map(lo).to_numpy()) & (t < sets.map(hi).to_numpy())
    if sel.sum() == 0:
        return 0.0
    return float(df["rating"].astype(float).to_numpy()[sel].mean())

# name: even_set_multiple_of_four_advantage
# description: In all-even sets whose examples are all multiples of 4, yes-rate for targets that are multiples of 4 minus even targets that are not; the model ties x4 to the same 'multiples' salience as x3/x9, so observed < null means it over-credits the x4 rule in even sets (people just use evenness), observed > null means it under-credits it.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    m = {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        m[s] = len(ex) >= 2 and all(e % 4 == 0 for e in ex)
    o = sets.map(m).to_numpy().astype(bool)
    t = df["target"].astype(int).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    a = o & (t % 4 == 0)
    b = o & (t % 2 == 0) & (t % 4 != 0)
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(y[a].mean() - y[b].mean())
